std::memset(bitmap, 0xffU, bitmap_size(binfo));
size_t extra = (BITMAP_GROUP_NBITS - (binfo->nbits & BITMAP_GROUP_NBITS_MASK)) & BITMAP_GROUP_NBITS_MASK;
if (extra != 0) {
    bitmap[bitmap_info_ngroups(binfo) - 1] >>= extra;
}
#ifdef BITMAP_USE_TREE
for (unsigned i = 1; i < binfo->nlevels; i++) {
    size_t group_count = binfo->levels[i].group_offset - binfo->levels[i-1].group_offset;
    extra = (BITMAP_GROUP_NBITS - (group_count & BITMAP_GROUP_NBITS_MASK)) & BITMAP_GROUP_NBITS_MASK;
    if (extra != 0) {
        bitmap[binfo->levels[i+1].group_offset - 1] >>= extra;
    }
}
#endif

